-- P5.8.2 READ ONLY. Aggregate-only. No IDs/PII, credentials, passwords, or raw provider results.
SELECT 'ELIGIBLE_PI' AS metric,COUNT(*) AS records,COALESCE(SUM(pi.expected_total),0) AS amount_idr FROM payment_instructions pi WHERE pi.status IN ('PAYMENT_APPROVAL_PENDING','APPROVED_FOR_PAYMENT') AND NOT EXISTS(SELECT 1 FROM payment_gateway_transactions gt WHERE gt.org_id=pi.org_id AND gt.payment_instruction_id=pi.id) AND NOT EXISTS(SELECT 1 FROM disbursement_requests dr WHERE dr.org_id=pi.org_id AND dr.source_document_type='PAYMENT_INSTRUCTION' AND dr.source_document_id=pi.id);
SELECT 'ELIGIBLE_SNAPSHOT_VALID' AS metric,COUNT(*) AS records,COALESCE(SUM(pi.expected_total),0) AS amount_idr FROM payment_instructions pi WHERE pi.status IN ('PAYMENT_APPROVAL_PENDING','APPROVED_FOR_PAYMENT') AND pi.expected_total>0 AND pi.content_hash IS NOT NULL AND pi.content_hash<>'' AND pi.recipient_count=(SELECT COUNT(*) FROM payment_instruction_lines pil WHERE pil.payment_instruction_id=pi.id) AND pi.expected_total=(SELECT COALESCE(SUM(amount),0) FROM payment_instruction_lines pil WHERE pil.payment_instruction_id=pi.id) AND NOT EXISTS(SELECT 1 FROM payment_instruction_lines pil WHERE pil.payment_instruction_id=pi.id AND (pil.account_ciphertext='' OR pil.account_iv='' OR pil.bank_code IS NULL OR pil.bank_code='' OR pil.line_hash IS NULL OR pil.line_hash='')) AND NOT EXISTS(SELECT 1 FROM payment_gateway_transactions gt WHERE gt.org_id=pi.org_id AND gt.payment_instruction_id=pi.id) AND NOT EXISTS(SELECT 1 FROM disbursement_requests dr WHERE dr.org_id=pi.org_id AND dr.source_document_type='PAYMENT_INSTRUCTION' AND dr.source_document_id=pi.id);
SELECT 'ELIGIBLE_PI_PROVIDER_BOUND' AS metric,COUNT(*) AS records,COALESCE(SUM(pi.expected_total),0) AS amount_idr FROM payment_instructions pi JOIN payroll_submissions ps ON ps.id=pi.submission_id AND ps.org_id=pi.org_id JOIN payment_provider_accounts ppa ON ppa.id=pi.provider_account_registry_id AND ppa.org_id=pi.org_id AND ppa.client_id=pi.client_id WHERE pi.status IN ('PAYMENT_APPROVAL_PENDING','APPROVED_FOR_PAYMENT') AND ppa.status='ACTIVE' AND ppa.provisioning_state='PROVISIONED' AND ppa.provider='E2PAY' AND ppa.account_scope='SUB_ACCOUNT' AND ppa.environment=pi.provider_environment AND ppa.provider_sub_account_id=pi.provider_sub_account_id AND (ppa.project_id IS NULL OR ppa.project_id=ps.project_id) AND NOT EXISTS(SELECT 1 FROM payment_gateway_transactions gt WHERE gt.org_id=pi.org_id AND gt.payment_instruction_id=pi.id) AND NOT EXISTS(SELECT 1 FROM disbursement_requests dr WHERE dr.org_id=pi.org_id AND dr.source_document_type='PAYMENT_INSTRUCTION' AND dr.source_document_id=pi.id);
SELECT 'ELIGIBLE_PI_LEGACY_MANUAL' AS metric,COUNT(*) AS records,COALESCE(SUM(pi.expected_total),0) AS amount_idr FROM payment_instructions pi JOIN provider_provisioning_sessions pps ON pps.provider_account_registry_id=pi.provider_account_registry_id AND pps.org_id=pi.org_id WHERE pi.status IN ('PAYMENT_APPROVAL_PENDING','APPROVED_FOR_PAYMENT') AND pps.credential_state='LEGACY_MANUAL' AND NOT EXISTS(SELECT 1 FROM payment_gateway_transactions gt WHERE gt.org_id=pi.org_id AND gt.payment_instruction_id=pi.id) AND NOT EXISTS(SELECT 1 FROM disbursement_requests dr WHERE dr.org_id=pi.org_id AND dr.source_document_type='PAYMENT_INSTRUCTION' AND dr.source_document_id=pi.id);
SELECT 'ELIGIBLE_PI_CREDENTIAL_HEALTHY' AS metric,COUNT(*) AS records,COALESCE(SUM(pi.expected_total),0) AS amount_idr FROM payment_instructions pi JOIN payment_provider_accounts ppa ON ppa.id=pi.provider_account_registry_id AND ppa.org_id=pi.org_id JOIN provider_provisioning_sessions pps ON pps.org_id=pi.org_id AND pps.provider_account_registry_id=ppa.id WHERE pi.status IN ('PAYMENT_APPROVAL_PENDING','APPROVED_FOR_PAYMENT') AND pps.credential_state='HEALTHY' AND pps.credential_version>0 AND json_valid(ppa.metadata_json) AND json_extract(ppa.metadata_json,'$.merchantCredential.ciphertext') IS NOT NULL AND json_extract(ppa.metadata_json,'$.merchantCredential.iv') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM payment_gateway_transactions gt WHERE gt.org_id=pi.org_id AND gt.payment_instruction_id=pi.id) AND NOT EXISTS(SELECT 1 FROM disbursement_requests dr WHERE dr.org_id=pi.org_id AND dr.source_document_type='PAYMENT_INSTRUCTION' AND dr.source_document_id=pi.id);
